<template>
    <div class="layout-px-spacing">  
        <ul class="navbar-nav flex-row mt-2">
            <li>
                <div class="page-header">
                    <nav class="breadcrumb-one" aria-label="breadcrumb">
                        <ol class="breadcrumb">
                            <li class="breadcrumb-item"><a href="javascript:;">Masters</a></li>
                            <li class="breadcrumb-item active" aria-current="page"><span> Jobcard Transfer Notes </span></li>
                        </ol>
                    </nav>
                </div>
            </li>
        </ul>

        <h3 class="text-center">JOBCARD TRANSFER NOTES</h3>

              <!-- loading spinner starts -->
        <div v-if="loading_spinner" v-html="tableShimmer()"></div>
        <!-- Loading spinner ends -->
        <div v-else class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
                <div class="panel p-0">
                    <div class="custom-table table3">
                        <v-client-table :data="transfer_notes" :columns="columns" :options="table_option">
                             <template #status="props">
            <span class="badge inv-status" :class="getStatusClass(props.row.status)">
                {{ props.row.status }}
            </span>
        </template>
                            <template #actions="props">
                              
                                                        <a 
    href="javascript:;"
    @click="handleJobcardOpen(props.row)"
    class="text-primary"
>
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" fill="currentColor" class="bi bi-eye" viewBox="0 0 16 16">
      <path d="M16 8s-3-5.5-8-5.5S0 8 0 8s3 5.5 8 5.5S16 8 16 8M1.173 8a13 13 0 0 1 1.66-2.043C4.12 4.668 5.88 3.5 8 3.5s3.879 1.168 5.168 2.457A13 13 0 0 1 14.828 8q-.086.13-.195.288c-.335.48-.83 1.12-1.465 1.755C11.879 11.332 10.119 12.5 8 12.5s-3.879-1.168-5.168-2.457A13 13 0 0 1 1.172 8z"/>
      <path d="M8 5.5a2.5 2.5 0 1 0 0 5 2.5 2.5 0 0 0 0-5M4.5 8a3.5 3.5 0 1 1 7 0 3.5 3.5 0 0 1-7 0"/>
    </svg>
</a>
                            </template>
                        </v-client-table>
                    </div>
                </div>
            </div>
        </div>

      

    </div>
</template>

<style>
    .table3 .actions svg {
        padding: 2px;
    }
</style>

<script setup>
    import { onMounted, ref, inject } from 'vue';
    import axios from 'axios';
    import { useMeta } from '@/composables/use-meta';
    import Multiselect from '@suadelabs/vue3-multiselect';
    import '@suadelabs/vue3-multiselect/dist/vue3-multiselect.css';
    import { useRouter } from 'vue-router';
    const router = useRouter();
    
    useMeta({ title: 'Jobcard Transfer Notes' });  



    const showMessage = inject('showMessage');
    const conversion_factor = ref(false);
    const showError = inject('showError');
    const user_permissions = JSON.parse(localStorage.getItem("user")).permissions;
    const formatDate = inject('formatDate');
    const tableShimmer = inject('tableShimmer');
    const loadingSpinner = inject('loadingSpinner'); 
    
    const loading_spinner = ref(false);
    const columns = ref(['SNo','date','jobcard','name','service_type','destination_location','issuer','remark','status','actions']);    
    const name = ref('');
    const quantity = ref('');
    const units = ref('');
    const items = ref([]);

    const table_option = ref({
        perPage: 20,
        perPageValues: [20, 50 ,100],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const axiosInstance = axios.create({
        baseURL: process.env.VUE_APP_API_BASE_URL
    });

   const transfer_notes = ref([])
    const getJobcardTransferNote = async () => {
        loading_spinner.value = true;
        try {
            const response = await axiosInstance.get('jobcard-transfer-notes');
            transfer_notes.value = response.data.map((item, index) => ({
                ...item,
                SNo: index + 1,
                id: item.id,
                jobcard : item.jobcard_id,
                destination_location : item.destination.name,
                issuer : item.issuer.name,
                asset_id : item.jobcard.machine_id,
                name : item.jobcard.machine.name + ' - ' + item.jobcard.machine.type_name,  
                remark : item.remark,  
                service_type : item.jobcard.service_type,                  
                status: item.status,          
                date:formatDate(item.date)                
            }));
        } catch (error) {
            showError(error.message);
            console.log (error)
        }finally{
            loading_spinner.value = false;
        }
    };


    const handleJobcardOpen = (jobcard) => {    
    router.push(`/jobcard/${jobcard.jobcard}/${jobcard.asset_id}`);    
};    

const getStatusClass = (status) => {
    if (!status) return 'badge-secondary';
    
    const statusUpper = status.toUpperCase();
    
    switch(statusUpper) {
        case 'APPROVED':
            return 'badge-success';
        case 'REJECTED':
            return 'badge-danger';
        case 'REMARKED':
            return 'badge-info';
        case 'ON HOLD':
            return 'badge-warning';
        case 'RECEIVED':
            return 'badge-primary';
        default:
            return 'badge-secondary';
    }
};

    onMounted(() => {
        getJobcardTransferNote();
       
    });
</script>